// Two variable definitions
const Index = OLI.random(0,5);
const array = [0.025,0.040,0.055,0.090,0.095];
const mol = array[Index] .toFixed(3);
const subtractFromCN = (2*mol) .toPrecision(3);
const initialConcCN = (1.0 - subtractFromCN) .toPrecision(3);
const initConcCNLow = (initialConcCN*0.99)
const initConcCNHigh = (initialConcCN*1.01);
const calcDenominator = (1100000000000000000*initialConcCN*initialConcCN);
const calcX = (mol/calcDenominator);
const concAg = (calcX) .toPrecision(2);
const concAgLow = calcX*0.98;
const concAgHigh = calcX*1.02;

// Expose variables to OLI
module.exports = {
 Index,
 array,
 mol,
 subtractFromCN,
 initialConcCN,
 initConcCNLow,
 initConcCNHigh,
 calcDenominator,
 calcX,
 concAg,
 concAgLow,
 concAgHigh
};
